mapper.select:
SELECT sm.id, li.remark, sm.shop_id, li.id AS listingId, si.name AS shopName, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name AS platformProductName, li.match_result, li.product_image_url, case when li.platform = 'AliExpress' then li.platform_sku_id else li.product_spec end as product_spec, li.product_packing, li.platform_update_time, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.create_time as systemCreateTime, li.source_type as sourceType, li.platform_status as platformStatus, li.platform_parent_sku_id as platformParentSkuId, sm.update_user_name, sm.effective_time, sm.expire_time, sm.update_time, ci.seller_name FROM sku_mapping sm LEFT JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT join customer_info ci on si.customer_id = ci.id and ci.is_deleted = false WHERE ${params.sqlMap.default} and sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
${params.permissionSql}
ORDER BY li.platform_sku_no,sm.create_time DESC

SELECT sm.id, sm.shop_id, li.remark, li.id AS listingId, si.name AS shopName, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name AS platformProductName, li.platform_sku_no AS sellerSkuNo, li.platform_sku_name AS sellerProductName, li.match_result, li.product_image_url, li.product_spec, li.product_packing, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.platform_update_time, li.create_time as systemCreateTime, sm.create_user_name, sm.create_time, sm.expire_time, sm.effective_time, ci.seller_name, it.invoice_hs_code, it.unit, it.diff_state_tax_code, it.same_state_tax_code, it.dict_origin, it.invoice_product_name FROM sku_mapping sm LEFT JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT join customer_info ci on si.customer_id = ci.id and ci.is_deleted = false left join invoice_tax it on li.id = it.listing_id and it.is_deleted = false WHERE ${params.sqlMap.default} and sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
${params.permissionSql}
ORDER BY li.platform_sku_no,sm.create_time DESC

SELECT li.match_result, count(sm.*) FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE AND li.is_deleted=FALSE
AND sm.type=#{params.type}
${params.permissionSql}
GROUP BY match_result

SELECT product_sku_id AS skuId, product_sku_no AS skuNo, li.platform_sku_no, platform_sku_name, li.product_image_url as imagesUrl FROM sku_mapping sm INNER join listing_info li on li.id = sm.listing_id and li.is_deleted = false WHERE sm.is_deleted=FALSE AND sm.is_expire=FALSE and li.auth_id = #{params.customerId}
AND ( sm.product_sku_no ILIKE concat('%',#{params.no}::text,'%') OR li.platform_sku_no ILIKE concat('%',#{params.no}::text,'%') )
AND (sm.product_sku_no IN
#{skuNo}
OR li.platform_sku_no IN
#{skuNo}
)

SELECT sm.id, li.id AS listingId, li.remark, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no AS warehouseSkuNo, li.platform_sku_name AS warehouseProductName, li.match_result, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.third_barcode, li.platform_sku_id, li.platform_status as platformStatus, li.platform_parent_sku_id as platformParentSkuId, sm.warehouse_id, sm.warehouse_name, sm.update_user_name, sm.update_time, sm.effective_time, sm.expire_time, sm.dict_platform, sm.platform_name, sm.has_mapping_all, op.short_name, li.auth_id as authId FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT JOIN overseas_provider op on op.id = li.auth_id and op.is_deleted = false WHERE ${params.sqlMap.default} and sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
${params.permissionSql}
ORDER BY li.platform_sku_no,sm.create_time DESC

SELECT sm.id, li.id AS listingId, li.remark, op.short_name as shortName, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no AS warehouseSkuNo, li.platform_sku_name AS warehouseProductName, li.platform_sku_id, li.match_result, li.third_barcode, sm.warehouse_id, sm.warehouse_name, sm.create_user_name, sm.create_time, sm.platform_name, sm.has_mapping_all, op.short_name, sm.effective_time, sm.expire_time FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT JOIN overseas_provider op on op.id = li.auth_id and op.is_deleted = false WHERE ${params.sqlMap.default} AND sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
${params.permissionSql}
ORDER BY li.platform_sku_no,sm.create_time DESC

SELECT li.id AS listingId, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name, li.type FROM listing_info li LEFT JOIN sku_mapping sm ON sm.listing_id = li.id AND li.is_deleted = FALSE WHERE sm.is_deleted = FALSE and sm.is_expire=FALSE
AND li.platform_sku_no IN
#{platformSkuNo}

SELECT li.id AS listingId,
sm.id,
li.auth_id as authId,
sm.product_sku_id,
sm.product_sku_no,
li.platform_sku_no AS platformSkuNo,
li.platform_sku_id as platformSkuId,
li.platform_sku_name AS platformProductName,
li.platform_spu_no AS platformSpuNo,
li.platform_spu_name AS platformSpuName
FROM sku_mapping sm
INNER JOIN listing_info li ON sm.listing_id = li.id AND li.is_deleted = FALSE
WHERE sm.is_deleted = FALSE
AND sm.is_expire=FALSE


    AND sm.product_sku_id IN

        #{item}




    AND li.platform_sku_no IN

        #{platformSkuNo}




    AND li.platform_spu_no IN

        #{platformSpuNo}




    AND li.platform = #{params.platform}
    AND sm.dict_platform = #{params.platform}


    AND li.auth_id = #{params.authId}



    AND li.match_result = #{params.matchResult}


    AND sm.shop_id IN

        #{shopId}

SELECT DISTINCT li.id AS listingId, sm.product_sku_id, sm.product_sku_no, sm.product_name, sm.warehouse_id, sm.warehouse_name, sm.dict_platform, li.platform_sku_no AS stockSku, li.platform_sku_name AS stockSkuName, sm.has_mapping_all as hasMappingAll FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE AND sm.is_expire=FALSE WHERE sm.is_deleted=FALSE
AND sm.product_sku_id IN
#{productSkuId}

SELECT sm.id as tableId, sm.shop_id, sm.listing_id, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, sm.product_name, sm.type, sm.warehouse_id, sm.warehouse_name, sm.effective_time, sm.expire_time, sm.is_expire, sm.has_mapping_all, li.id as listingId, li.platform_sku_no, li.platform_sku_name, li.platform, li.match_result, li.product_image_url, li.product_spec, li.product_packing, li.platform_update_time, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.platform_sku_id as platformSkuId, li.auth_id as authId, li.platform_status as platformStatus, li.is_parent as isParent FROM sku_mapping sm LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE WHERE sm.is_deleted=FALSE
AND sm.is_expire = #{params.isExpire}
AND sm.id IN
#{skuMappingId}
AND li.platform_sku_no IN
#{platformSkuNo}
AND li.platform_spu_no IN
#{platformSpuNo}
AND li.platform_sku_id IN
#{item}
AND sm.product_sku_no IN
#{skuNo}
AND sm.product_sku_id IN
#{item}
AND sm.type =#{params.type}
AND li.platform = #{params.platform} AND sm.dict_platform = #{params.platform}
AND li.platform IN
#{item}
AND sm.dict_platform in
#{item}
AND li.match_result = #{params.matchResult}
AND sm.shop_id IN
#{shopId}
AND sm.warehouse_id IN
#{warehouseId}

select sm.id as tableId, sm.shop_id as shopId, sm.dict_platform as dictPlatform, sm.platform_name as platformName, sm.product_sku_id as productSkuId, sm.product_sku_no as productSkuNo, sm.product_name as productName, sm.type as type, sm.warehouse_id as warehouseId, sm.warehouse_name as warehouseName, sm.effective_time as effectiveTime, sm.expire_time as expireTime, sm.is_expire as isExpire, sm.has_mapping_all as hasMappingAll, li.id as listingId, li.platform_sku_no as platformSkuNo, li.platform_sku_name as platformSkuName, li.platform_spu_no as platformSpuNo, li.platform_spu_name as platformSpuName, li.platform as platform, li.match_result as matchResult, li.product_image_url as productImageUrl, li.product_spec as productSpec, li.product_packing as productPacking, li.platform_fn_sku as platformFnSku from sku_mapping sm inner join listing_info li on sm.listing_id = li.id where sm.is_deleted = false and li.is_deleted = false and sm.is_expire = false
AND sm.product_sku_id IN
#{item}
AND sm.shop_id = #{shopId}
AND li.platform = #{provideCode} AND sm.dict_platform = #{provideCode}
and sm.warehouse_id = #{warehouseId}

select sm.id as mappingId, sm.dict_platform as dictPlatform, sm.product_sku_id as productSkuId, sm.product_sku_no as productSkuNo, sm.product_name as productName, sm.platform_name as platformName, sm.type as type, sm.warehouse_id as warehouseId, sm.warehouse_name as warehouseName, sm.is_expire as isExpire, li.id as listingId, li.auth_id as customerId, li.platform_sku_no as platformSkuNo, li.platform_sku_name as platformSkuName, li.third_barcode as thirdBarcode, li.platform_spu_no as platformSpuNo, li.platform_spu_name as platformSpuName, li.platform_fn_sku as platformFnSku, op.short_name from sku_mapping sm inner join listing_info li on sm.listing_id = li.id and li.is_deleted = false LEFT JOIN overseas_provider op on op.id = li.auth_id and op.is_deleted = false where sm.is_deleted = false and sm.is_expire = false
AND li.type = #{params.type} AND sm.type = #{params.type}
AND li.auth_id = #{params.authId}
AND li.platform_sku_no IN
#{item}

SELECT sm.id, li.id AS listingId, ci.platform_type as platformName, ci.id as customerId, ci.name as customerName, ci.seller_name as sellerName, li.product_image_url as productImageUrl, li.platform_sku_no AS platformSkuNo, li.platform_sku_name AS platformSkuName, sm.product_sku_id as productSkuId, sm.product_sku_no as productSkuNo, sm.product_name as productName, li.match_result, li.remark, li.label_url as labelUrl, li.label_file_name as labelFileName, li.label_source_type as labelSourceType, li.platform_status as platformStatus, li.platform_parent_sku_id as platformParentSkuId, sm.create_user_name as createUserName, sm.create_time as createTime, sm.update_user_name as updateUserName, sm.update_time as updateTime, sm.effective_time as effectiveTime FROM sku_mapping sm INNER JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT JOIN customer_info ci on ci.id = li.auth_id and ci.is_deleted = false WHERE ${params.sqlMap.default} and sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
ORDER BY li.create_time DESC, li.platform_sku_no

SELECT sm.id, li.remark, sm.shop_id, li.id AS listingId, si.name AS shopName, sm.dict_platform, sm.platform_name, sm.product_sku_id, sm.product_sku_no, li.platform_sku_no, li.platform_sku_name AS platformProductName, li.match_result, li.product_image_url, case when li.platform = 'AliExpress' then li.platform_sku_id else li.product_spec end as product_spec, li.product_packing, li.platform_update_time, li.platform_spu_no, li.platform_spu_name, li.platform_fn_sku, li.create_time as systemCreateTime, li.source_type as sourceType, sm.update_user_name, sm.effective_time, sm.expire_time, sm.update_time, ci.seller_name FROM sku_mapping sm LEFT JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE LEFT JOIN listing_info li ON sm.listing_id=li.id AND li.is_deleted=FALSE LEFT join customer_info ci on si.customer_id = ci.id and ci.is_deleted = false WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.type =#{params.type}
AND li.platform_sku_no =#{params.platformSkuNo}
AND si.account =#{params.account}
AND sm.dict_platform =#{params.dictPlatform}
ORDER BY li.platform_sku_no,sm.create_time DESC

SELECT sm.ID, sm.shop_id, si.customer_id, sm.listing_id, sm.dict_platform, sm.platform_name, sm.product_sku_id AS skuId, sm.product_sku_no AS skuNo, sm.product_name AS skuName, li.platform_sku_no, li.platform_sku_name from sku_mapping sm INNER JOIN shop_info si ON sm.shop_id = si.ID AND si.is_deleted =FALSE INNER JOIN listing_info li ON sm.listing_id = li.ID AND li.is_deleted = FALSE INNER JOIN customer_info ci ON si.customer_id = ci.ID AND ci.is_deleted = FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire=FALSE
and si.customer_id = #{params.cutomerId}
AND sm.product_sku_id IN
#{skuId}
AND sm.product_sku_no IN
#{skuNo}
AND li.platform_sku_no IN
#{skuNo}
